const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/app/dashboard/emails/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Mail, Send, Users, Zap, Plus, Eye, BarChart2, X, Loader2, Check } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\" };\n\nconst CAMPAIGN_TYPES = [\n  { id:\"welcome\",    emoji:\"👋\", label:\"Welcome Series\",     desc:\"Automated email when someone joins your store\" },\n  { id:\"winback\",    emoji:\"💝\", label:\"Win-Back\",           desc:\"Re-engage customers who haven't bought in 30+ days\" },\n  { id:\"abandoned\",  emoji:\"🛒\", label:\"Cart Recovery\",      desc:\"Recover abandoned checkout sessions\" },\n  { id:\"newsletter\", emoji:\"📰\", label:\"Newsletter\",         desc:\"Regular updates to your entire list\" },\n  { id:\"promo\",      emoji:\"🎉\", label:\"Promotional\",        desc:\"Announce sales, new arrivals, events\" },\n];\n\nfunction CampaignCard({ c, t, onSend, sending }: any) {\n  const statusColor = c.status === \"active\" ? V.green : c.status === \"sent\" ? V.v400 : V.amber;\n  const isSent = c.status === \"sent\";\n  return (\n    <div className=\"flex items-center gap-4 p-4 rounded-2xl\" style={{ background:t.faint, border:`1px solid ${t.border}` }}>\n      <div className=\"text-2xl flex-shrink-0\">{c.emoji || \"📧\"}</div>\n      <div className=\"flex-1 min-w-0\">\n        <p className=\"text-sm font-semibold\" style={{ color:t.text }}>{c.name}</p>\n        <p className=\"text-xs mt-0.5\" style={{ color:t.muted }}>\n          {c.recipients?.toLocaleString() || 0} recipients\n          {c.openRate ? ` · ${c.openRate}% open rate` : \"\"}\n          {c.sentAt ? ` · Sent ${new Date(c.sentAt).toLocaleDateString()}` : \"\"}\n        </p>\n      </div>\n      <div className=\"flex items-center gap-2 flex-shrink-0\">\n        {c.openRate && (\n          <div className=\"text-right hidden sm:block\">\n            <p className=\"text-sm font-bold\" style={{ color:t.text }}>{c.openRate}%</p>\n            <p className=\"text-xs\" style={{ color:t.muted }}>opened</p>\n          </div>\n        )}\n        {!isSent && (\n          <button onClick={() => onSend(c.id)} disabled={sending}\n            className=\"flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold text-white\"\n            style={{ background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, border:\"none\", cursor:\"pointer\", opacity:sending?0.6:1 }}>\n            {sending ? <Loader2 size={11} style={{animation:\"spin 1s linear infinite\"}}/> : <Send size={11}/>}\n            Send\n          </button>\n        )}\n        <span className=\"text-xs font-semibold px-2.5 py-1 rounded-full\"\n          style={{ color:statusColor, background:`${statusColor}18` }}>\n          {c.status || \"draft\"}\n        </span>\n      </div>\n    </div>\n  );\n}\n\nfunction NewCampaignModal({ onClose, storeId, t, isDark }: any) {\n  const qc = useQueryClient();\n  const [type, setType]       = useState(\"newsletter\");\n  const [name, setName]       = useState(\"\");\n  const [subject, setSubject] = useState(\"\");\n  const [body, setBody]       = useState(\"\");\n  const [writing, setWriting] = useState(false);\n\n  const createMut = useMutation({\n    mutationFn: () => api.post(`/emails/${storeId}/campaigns`, { type, name, subject, body }),\n    onSuccess: () => { toast.success(\"Campaign created!\"); qc.invalidateQueries({queryKey:[\"email-campaigns\"]}); onClose(); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed\"),\n  });\n\n  const writeWithKiro = async () => {\n    setWriting(true);\n    try {\n      const tpl = CAMPAIGN_TYPES.find(t => t.id === type);\n      const r = await api.post(\"/kai/smart-chat\", {\n        message: `Write a ${tpl?.label} email for my store. Subject line and body. Keep it warm, concise, and action-oriented. Return format: SUBJECT: [subject]\\n\\nBODY:\\n[body]`,\n        storeId,\n      });\n      const text = r.data?.data?.reply || r.data?.reply || \"\";\n      const subMatch = text.match(/SUBJECT:\\s*(.+)/);\n      const bodyMatch = text.match(/BODY:\\s*([\\s\\S]+)/);\n      if (subMatch) setSubject(subMatch[1].trim());\n      if (bodyMatch) setBody(bodyMatch[1].trim());\n      toast.success(\"KIRO wrote your email\");\n    } catch { toast.error(\"KIRO offline\"); }\n    setWriting(false);\n  };\n\n  const inp = { width:\"100%\", padding:\"10px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:isDark?\"rgba(255,255,255,0.05)\":\"#F0EDFF\", color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\" } as const;\n\n  return (\n    <div className=\"fixed inset-0 z-50 flex items-center justify-center p-4\" style={{ background:\"rgba(0,0,0,0.6)\", backdropFilter:\"blur(8px)\" }} onClick={e => e.target === e.currentTarget && onClose()}>\n      <motion.div initial={{opacity:0,scale:0.95,y:16}} animate={{opacity:1,scale:1,y:0}}\n        className=\"w-full max-w-lg rounded-2xl overflow-hidden\"\n        style={{ background:isDark?\"#181230\":\"#fff\", border:`1px solid ${t.border}`, maxHeight:\"90vh\", overflowY:\"auto\" }}>\n        <div className=\"flex items-center justify-between p-5\" style={{ borderBottom:`1px solid ${t.border}` }}>\n          <h3 className=\"font-black text-base\" style={{ color:t.text }}>New Email Campaign</h3>\n          <button onClick={onClose} style={{ border:\"none\", background:\"none\", cursor:\"pointer\", color:t.muted }}><X size={18}/></button>\n        </div>\n        <div className=\"p-5 space-y-4\">\n          {/* Type picker */}\n          <div>\n            <label className=\"block text-xs font-semibold mb-2\" style={{ color:t.muted }}>Campaign Type</label>\n            <div className=\"space-y-2\">\n              {CAMPAIGN_TYPES.map(ct => (\n                <button key={ct.id} onClick={() => setType(ct.id)}\n                  className=\"w-full flex items-center gap-3 p-3 rounded-xl text-left transition-all\"\n                  style={{ border:`1px solid ${type===ct.id?\"rgba(107,53,232,0.4)\":t.border}`, background:type===ct.id?\"rgba(107,53,232,0.08)\":t.faint, cursor:\"pointer\" }}>\n                  <span className=\"text-xl flex-shrink-0\">{ct.emoji}</span>\n                  <div className=\"flex-1 min-w-0\">\n                    <p className=\"text-xs font-bold\" style={{ color:type===ct.id?V.v300:t.text }}>{ct.label}</p>\n                    <p className=\"text-xs\" style={{ color:t.muted }}>{ct.desc}</p>\n                  </div>\n                  {type === ct.id && <Check size={14} color={V.v400} className=\"flex-shrink-0\"/>}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:t.muted }}>Campaign Name</label>\n            <input value={name} onChange={e => setName(e.target.value)} placeholder=\"May Newsletter\" style={inp}/>\n          </div>\n\n          <div>\n            <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:t.muted }}>Subject Line</label>\n            <input value={subject} onChange={e => setSubject(e.target.value)} placeholder=\"Something exciting is here...\" style={inp}/>\n          </div>\n\n          <div className=\"relative\">\n            <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:t.muted }}>Email Body</label>\n            <textarea value={body} onChange={e => setBody(e.target.value)} rows={6}\n              placeholder=\"Write your email content...\" style={{...inp, resize:\"none\", display:\"block\"}}/>\n            <button onClick={writeWithKiro} disabled={writing}\n              className=\"absolute bottom-3 right-3 flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold text-white\"\n              style={{ background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, border:\"none\", cursor:\"pointer\", opacity:writing?0.7:1 }}>\n              {writing ? <Loader2 size={11} style={{animation:\"spin 1s linear infinite\"}}/> : <Zap size={11}/>}\n              KIRO\n            </button>\n          </div>\n        </div>\n        <div className=\"p-5 flex gap-3\" style={{ borderTop:`1px solid ${t.border}` }}>\n          <button onClick={onClose} className=\"flex-1 py-2.5 rounded-xl text-sm font-semibold\"\n            style={{ border:`1px solid ${t.border}`, background:\"transparent\", cursor:\"pointer\", color:t.muted }}>Cancel</button>\n          <button onClick={() => createMut.mutate()} disabled={!name||!subject||createMut.isPending}\n            className=\"flex-1 py-2.5 rounded-xl text-sm font-bold text-white flex items-center justify-center gap-2\"\n            style={{ background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, border:\"none\", cursor:\"pointer\", opacity:!name||!subject?0.6:1 }}>\n            {createMut.isPending ? <Loader2 size={13} style={{animation:\"spin 1s linear infinite\"}}/> : <Plus size={13}/>}\n            Create Campaign\n          </button>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\nexport default function EmailsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.08)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.55)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.03)\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [showNew, setShowNew] = useState(false);\n  const [sending, setSending] = useState<string|null>(null);\n\n  const sendMut = useMutation({\n    mutationFn: (campaignId: string) => api.post(`/emails/${storeId}/campaigns/${campaignId}/send`, { storeId }),\n    onSuccess: () => { toast.success(\"Campaign sent to all customers! 🎉\"); qc.invalidateQueries({queryKey:[\"email-campaigns\"]}); setSending(null); },\n    onError: (e: any) => { toast.error(e.response?.data?.message || \"Send failed — check RESEND_API_KEY in Render\"); setSending(null); },\n  });\n\n  const handleSend = (campaignId: string) => {\n    if (!confirm(\"Send this campaign to all your customers now?\")) return;\n    setSending(campaignId);\n    sendMut.mutate(campaignId);\n  };\n\n  const { data: campaigns } = useQuery({\n    queryKey: [\"email-campaigns\", storeId],\n    queryFn: () => api.get(`/emails/${storeId}/campaigns`).then(r => r.data.data || []),\n    enabled: !!storeId,\n  });\n\n  const { data: stats } = useQuery({\n    queryKey: [\"email-stats\", storeId],\n    queryFn: () => api.get(`/customers/${storeId}/stats`).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  return (\n    <div className=\"max-w-4xl mx-auto\">\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} className=\"flex items-center justify-between mb-6 flex-wrap gap-3\">\n        <div>\n          <h1 className=\"text-xl sm:text-2xl font-black tracking-tight mb-1\" style={{ color:t.text }}>Email Campaigns</h1>\n          <p className=\"text-sm\" style={{ color:t.muted }}>{campaigns?.length || 0} campaigns · {stats?.totalCustomers || 0} subscribers</p>\n        </div>\n        <button onClick={() => setShowNew(true)}\n          className=\"flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold text-white\"\n          style={{ background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, border:\"none\", cursor:\"pointer\" }}>\n          <Plus size={15}/> New Campaign\n        </button>\n      </motion.div>\n\n      {/* Stats */}\n      <div className=\"grid grid-cols-3 gap-3 mb-6\">\n        {[\n          { label:\"Subscribers\", value:(stats?.totalCustomers||0).toLocaleString(), icon:Users,    color:V.v400  },\n          { label:\"Avg Open Rate\",value:\"--\",                                        icon:Eye,      color:V.green },\n          { label:\"Campaigns\",    value:(campaigns?.length||0).toString(),            icon:BarChart2,color:V.amber },\n        ].map((s,i) => (\n          <motion.div key={s.label} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.06}}\n            className=\"p-4 rounded-2xl\" style={{ background:t.card, border:`1px solid ${t.border}` }}>\n            <div className=\"w-8 h-8 rounded-xl flex items-center justify-center mb-2\" style={{ background:`${s.color}15` }}>\n              <s.icon size={14} style={{ color:s.color }}/>\n            </div>\n            <p className=\"text-xl font-black mb-0.5\" style={{ color:t.text }}>{s.value}</p>\n            <p className=\"text-xs\" style={{ color:t.muted }}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Campaign types info */}\n      <div className=\"rounded-2xl overflow-hidden mb-5\" style={{ background:t.card, border:`1px solid ${t.border}` }}>\n        <div className=\"px-5 py-4\" style={{ borderBottom:`1px solid ${t.border}` }}>\n          <p className=\"text-xs font-bold uppercase tracking-widest\" style={{ color:t.muted }}>Automated Campaigns</p>\n        </div>\n        <div className=\"divide-y\" style={{ borderColor:t.border }}>\n          {CAMPAIGN_TYPES.slice(0,3).map((ct, i) => (\n            <div key={ct.id} className=\"flex items-center gap-4 px-5 py-3.5\">\n              <span className=\"text-xl flex-shrink-0\">{ct.emoji}</span>\n              <div className=\"flex-1\">\n                <p className=\"text-sm font-semibold\" style={{ color:t.text }}>{ct.label}</p>\n                <p className=\"text-xs\" style={{ color:t.muted }}>{ct.desc}</p>\n              </div>\n              <span className=\"text-xs font-semibold px-2.5 py-1 rounded-full\" style={{ background:\"rgba(107,53,232,0.1)\", color:V.v400 }}>\n                Auto\n              </span>\n            </div>\n          ))}\n        </div>\n      </div>\n\n      {/* Campaigns list */}\n      {!campaigns?.length ? (\n        <div className=\"text-center py-16 rounded-2xl\" style={{ background:t.faint, border:`1px solid ${t.border}` }}>\n          <Mail size={36} style={{ color:t.muted, margin:\"0 auto 12px\" }}/>\n          <p className=\"font-bold text-base mb-2\" style={{ color:t.text }}>No campaigns yet</p>\n          <p className=\"text-sm mb-6\" style={{ color:t.muted }}>Create your first email campaign. KIRO writes the content.</p>\n          <button onClick={() => setShowNew(true)}\n            className=\"inline-flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold text-white\"\n            style={{ background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, border:\"none\", cursor:\"pointer\" }}>\n            <Plus size={14}/> Create Campaign\n          </button>\n        </div>\n      ) : (\n        <div className=\"space-y-3\">\n          {campaigns.map((c: any, i: number) => (\n            <motion.div key={c.id} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.04}}>\n              <CampaignCard c={c} t={t} onSend={handleSend} sending={sending === c.id}/>\n            </motion.div>\n          ))}\n        </div>\n      )}\n\n      <AnimatePresence>\n        {showNew && <NewCampaignModal onClose={() => setShowNew(false)} storeId={storeId} t={t} isDark={isDark}/>}\n      </AnimatePresence>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/fulfillment/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { Package, Truck, Check, Clock, Zap, RefreshCw, AlertTriangle, ExternalLink, Loader2 } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\n\nconst STATUS: Record<string,any> = {\n  UNFULFILLED: { label:\"Unfulfilled\", color:V.amber, bg:\"rgba(245,158,11,0.1)\",  icon:Clock   },\n  PROCESSING:  { label:\"Processing\",  color:V.cyan,  bg:\"rgba(6,182,212,0.1)\",  icon:RefreshCw },\n  SHIPPED:     { label:\"Shipped\",     color:V.green, bg:\"rgba(16,185,129,0.1)\", icon:Truck   },\n  DELIVERED:   { label:\"Delivered\",   color:V.v400,  bg:\"rgba(107,53,232,0.1)\", icon:Check   },\n  FAILED:      { label:\"Failed\",      color:V.red,   bg:\"rgba(239,68,68,0.1)\",  icon:AlertTriangle },\n};\n\nfunction fmt(n: number) {\n  return new Intl.NumberFormat(\"en-NG\",{style:\"currency\",currency:\"NGN\",maximumFractionDigits:0}).format(n||0);\n}\n\nexport default function FulfillmentPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.07)\" : \"rgba(107,53,232,0.08)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.45)\" : \"rgba(19,13,46,0.55)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.03)\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const [showCJModal, setShowCJModal] = useState(false);\n  const [cjEmail, setCJEmail] = useState(\"\");\n  const [cjPassword, setCJPassword] = useState(\"\");\n\n  const { data: integrations } = useQuery({\n    queryKey: [\"fulfillment-integrations\", storeId],\n    queryFn: () => api.get(`/fulfillment/status/${storeId}`).then(r => r.data.data?.integrations || {}).catch(() => ({})),\n    enabled: !!storeId,\n  });\n\n  const cjMut = useMutation({\n    mutationFn: () => api.post(\"/fulfillment/connect/cj\", { storeId, email: cjEmail, password: cjPassword }),\n    onSuccess: () => { toast.success(\"CJDropshipping connected! Auto-fulfillment is now active.\"); setShowCJModal(false); qc.invalidateQueries({queryKey:[\"fulfillment-integrations\"]}); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Connection failed — check your CJ credentials\"),\n  });\n\n  const cjConnected = integrations?.cj?.connected;\n  const qc = useQueryClient();\n  const [tab, setTab] = useState(\"UNFULFILLED\");\n\n  const { data, isLoading, refetch } = useQuery({\n    queryKey: [\"fulfillment\", storeId, tab],\n    queryFn:  async () => {\n      const r = await api.get(`/fulfillment/status/${storeId}?status=${tab}`);\n      const d = r.data?.data;\n      return Array.isArray(d) ? d : [];\n    },\n    enabled:  !!storeId,\n    refetchInterval: 30000,\n  });\n\n  const { data: stats } = useQuery({\n    queryKey: [\"fulfillment-stats\", storeId],\n    queryFn:  () => api.get(`/analytics/${storeId}?period=30`).then(r => r.data.data),\n    enabled:  !!storeId,\n  });\n\n  const fulfillMut = useMutation({\n    mutationFn: (orderId: string) => api.post(`/fulfillment/${orderId}/fulfill`, { storeId }),\n    onSuccess: () => { toast.success(\"Order fulfilled!\"); qc.invalidateQueries({queryKey:[\"fulfillment\"]}); },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Fulfillment failed\"),\n  });\n\n  const orders = Array.isArray(data) ? data : [];\n  const pending    = orders.filter((o: any) => o.fulfillmentStatus === \"UNFULFILLED\").length;\n  const processing = orders.filter((o: any) => o.fulfillmentStatus === \"PROCESSING\").length;\n\n  return (\n    <div className=\"max-w-5xl mx-auto\">\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} className=\"flex items-start justify-between mb-6 flex-wrap gap-3\">\n        <div>\n          <h1 className=\"text-xl sm:text-2xl font-black tracking-tight mb-1\" style={{ color:t.text }}>Fulfilment</h1>\n          <p className=\"text-sm\" style={{ color:t.muted }}>\n            {pending > 0 && <span style={{ color:V.amber }}>{pending} need attention · </span>}\n            KIRO auto-fulfils with connected suppliers\n          </p>\n        </div>\n        {/* CJDropshipping connect banner */}\n        {!cjConnected && (\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10, padding:\"10px 16px\", borderRadius:12,\n            background:\"rgba(6,182,212,0.05)\", border:\"1px solid rgba(6,182,212,0.2)\" }}>\n            <span style={{ fontSize:18 }}>🔗</span>\n            <p style={{ fontSize:13, color:\"#06B6D4\", fontWeight:600, margin:0, flex:1 }}>\n              Connect CJDropshipping to enable one-click auto-fulfillment\n            </p>\n            <button onClick={() => setShowCJModal(true)}\n              style={{ padding:\"7px 14px\", borderRadius:9, border:\"none\", cursor:\"pointer\",\n                background:\"linear-gradient(135deg,#06B6D4,#0891B2)\", color:\"#fff\",\n                fontSize:12, fontWeight:700, fontFamily:\"inherit\", whiteSpace:\"nowrap\" }}>\n              Connect CJ\n            </button>\n          </div>\n        )}\n        {cjConnected && (\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px 14px\", borderRadius:10,\n            background:\"rgba(16,185,129,0.06)\", border:\"1px solid rgba(16,185,129,0.15)\" }}>\n            <span style={{ fontSize:14 }}>✅</span>\n            <p style={{ fontSize:12, color:\"#10B981\", fontWeight:700, margin:0 }}>\n              CJDropshipping connected · Auto-fulfillment active\n            </p>\n          </div>\n        )}\n        <div className=\"flex gap-2\">\n          <button onClick={() => refetch()}\n            className=\"flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold\"\n            style={{ border:`1px solid ${t.border}`, background:t.faint, cursor:\"pointer\", color:t.muted }}>\n            <RefreshCw size={12}/> Refresh\n          </button>\n          <div className=\"flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold\"\n            style={{ background:\"rgba(107,53,232,0.08)\", border:\"1px solid rgba(107,53,232,0.2)\", color:V.v400 }}>\n            <Zap size={12}/> KIRO Auto-Pilot {processing > 0 ? \"Active\" : \"Ready\"}\n          </div>\n        </div>\n      </motion.div>\n\n      {/* Stats */}\n      <div className=\"grid grid-cols-2 sm:grid-cols-4 gap-3 mb-5\">\n        {[\n          { label:\"Pending\",    value:pending,                                     color:V.amber },\n          { label:\"Processing\", value:processing,                                  color:V.cyan  },\n          { label:\"Shipped Today\",value:stats?.shippedToday || 0,                  color:V.green },\n          { label:\"Avg Ship Time\",value:`${stats?.avgShipDays || 2}d`,             color:V.v400  },\n        ].map((s, i) => (\n          <motion.div key={s.label} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.06}}\n            className=\"p-4 rounded-2xl\" style={{ background:t.card, border:`1px solid ${t.border}` }}>\n            <p className=\"text-2xl font-black mb-0.5\" style={{ color:s.color }}>{s.value}</p>\n            <p className=\"text-xs\" style={{ color:t.muted }}>{s.label}</p>\n          </motion.div>\n        ))}\n      </div>\n\n      {/* Tabs */}\n      <div className=\"flex gap-2 mb-5 flex-wrap\">\n        {Object.entries(STATUS).map(([id, cfg]) => (\n          <button key={id} onClick={() => setTab(id)}\n            className=\"px-3 py-1.5 rounded-xl text-xs font-semibold\"\n            style={{ background:tab===id?cfg.bg:\"transparent\", color:tab===id?cfg.color:t.muted, border:`1px solid ${tab===id?cfg.color+\"40\":t.border}`, cursor:\"pointer\" }}>\n            {cfg.label}\n          </button>\n        ))}\n      </div>\n\n      {/* Orders */}\n      {isLoading ? (\n        <div className=\"text-center py-16\" style={{ color:t.muted }}>Loading...</div>\n      ) : orders.length === 0 ? (\n        <div className=\"text-center py-16 rounded-2xl\" style={{ background:t.faint, border:`1px solid ${t.border}` }}>\n          <Package size={36} style={{ color:t.muted, margin:\"0 auto 12px\" }}/>\n          <p className=\"font-bold text-base mb-2\" style={{ color:t.text }}>No {tab.toLowerCase()} orders</p>\n          <p className=\"text-sm\" style={{ color:t.muted }}>\n            {tab === \"UNFULFILLED\" ? \"All orders are fulfilled. Great work!\" : `No ${tab.toLowerCase()} orders right now.`}\n          </p>\n        </div>\n      ) : (\n        <div className=\"space-y-3\">\n          {orders.map((order: any, i: number) => {\n            const cfg = STATUS[order.fulfillmentStatus || \"UNFULFILLED\"] || STATUS[\"UNFULFILLED\"];\n            const Icon = cfg.icon;\n            return (\n              <motion.div key={order.id} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} transition={{delay:i*0.04}}\n                className=\"flex items-center gap-4 p-4 rounded-2xl\" style={{ background:t.card, border:`1px solid ${t.border}` }}>\n                <div className=\"w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0\" style={{ background:cfg.bg }}>\n                  <Icon size={16} style={{ color:cfg.color }}/>\n                </div>\n                <div className=\"flex-1 min-w-0\">\n                  <div className=\"flex items-center gap-2 mb-0.5\">\n                    <p className=\"text-sm font-bold\" style={{ color:t.text }}>#{order.orderNumber || order.id?.slice(-8)}</p>\n                    <span className=\"text-xs font-semibold px-2 py-0.5 rounded-full\" style={{ color:cfg.color, background:cfg.bg }}>\n                      {cfg.label}\n                    </span>\n                  </div>\n                  <p className=\"text-xs\" style={{ color:t.muted }}>\n                    {order.customerName || order.customer?.name || \"Customer\"} · {fmt(order.total)}\n                    {order.trackingNumber && ` · ${order.trackingNumber}`}\n                  </p>\n                </div>\n                <div className=\"flex items-center gap-2 flex-shrink-0\">\n                  {order.trackingUrl && (\n                    <a href={order.trackingUrl} target=\"_blank\" rel=\"noreferrer\"\n                      style={{ width:32, height:32, borderRadius:10, border:`1px solid ${t.border}`, background:t.faint, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", textDecoration:\"none\" }}>\n                      <ExternalLink size={13} style={{ color:t.muted }}/>\n                    </a>\n                  )}\n                  {(order.fulfillmentStatus === \"UNFULFILLED\" || !order.fulfillmentStatus) && (\n                    <button onClick={() => fulfillMut.mutate(order.id)}\n                      disabled={fulfillMut.isPending}\n                      className=\"flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold text-white\"\n                      style={{ background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, border:\"none\", cursor:\"pointer\" }}>\n                      {fulfillMut.isPending ? <Loader2 size={11} style={{animation:\"spin 1s linear infinite\"}}/> : <Zap size={11}/>}\n                      Fulfil\n                    </button>\n                  )}\n                </div>\n              </motion.div>\n            );\n          })}\n        </div>\n      )}\n\n      {/* CJDropshipping Connect Modal */}\n      {showCJModal && (\n        <div style={{ position:\"fixed\", inset:0, zIndex:50, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", padding:16, background:\"rgba(0,0,0,0.6)\", backdropFilter:\"blur(8px)\" }}\n          onClick={e => e.target === e.currentTarget && setShowCJModal(false)}>\n          <div style={{ width:\"100%\", maxWidth:420, borderRadius:20, overflow:\"hidden\", background: isDark?\"#181230\":\"#fff\", border:`1px solid ${t.border}` }}>\n            <div style={{ padding:\"20px 24px\", borderBottom:`1px solid ${t.border}`, display:\"flex\", alignItems:\"center\", gap:12 }}>\n              <div style={{ width:36, height:36, borderRadius:10, background:\"rgba(6,182,212,0.1)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                <Zap size={16} color=\"#06B6D4\"/>\n              </div>\n              <div>\n                <p style={{ fontSize:15, fontWeight:800, color:t.text, margin:0 }}>Connect CJDropshipping</p>\n                <p style={{ fontSize:12, color:t.muted, margin:0 }}>Enter your CJ account credentials</p>\n              </div>\n            </div>\n            <div style={{ padding:24 }}>\n              <p style={{ fontSize:13, color:t.muted, margin:\"0 0 16px\", lineHeight:1.6 }}>\n                Once connected, KIRO will automatically place orders with CJDropshipping when customers buy from your store.\n              </p>\n              <div style={{ marginBottom:12 }}>\n                <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:5 }}>CJ Email</label>\n                <input value={cjEmail} onChange={e => setCJEmail(e.target.value)} type=\"email\" placeholder=\"your@email.com\"\n                  style={{ width:\"100%\", padding:\"10px 14px\", borderRadius:11, border:`1px solid ${t.border}`, background:isDark?\"rgba(255,255,255,0.05)\":\"#f5f3ff\", color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\" }}/>\n              </div>\n              <div style={{ marginBottom:20 }}>\n                <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:5 }}>CJ Password</label>\n                <input value={cjPassword} onChange={e => setCJPassword(e.target.value)} type=\"password\" placeholder=\"••••••••\"\n                  style={{ width:\"100%\", padding:\"10px 14px\", borderRadius:11, border:`1px solid ${t.border}`, background:isDark?\"rgba(255,255,255,0.05)\":\"#f5f3ff\", color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\" }}/>\n              </div>\n              <p style={{ fontSize:11, color:t.muted, margin:\"0 0 16px\" }}>\n                Don't have a CJ account? <a href=\"https://cjdropshipping.com\" target=\"_blank\" rel=\"noreferrer\" style={{ color:\"#06B6D4\", textDecoration:\"none\", fontWeight:600 }}>Sign up free →</a>\n              </p>\n              <div style={{ display:\"flex\", gap:10 }}>\n                <button onClick={() => setShowCJModal(false)}\n                  style={{ flex:1, padding:\"11px 0\", borderRadius:12, border:`1px solid ${t.border}`, background:\"transparent\", color:t.muted, cursor:\"pointer\", fontFamily:\"inherit\", fontSize:13, fontWeight:600 }}>\n                  Cancel\n                </button>\n                <button onClick={() => cjMut.mutate()} disabled={!cjEmail || !cjPassword || cjMut.isPending}\n                  style={{ flex:2, padding:\"11px 0\", borderRadius:12, border:\"none\", cursor:\"pointer\", background:\"linear-gradient(135deg,#06B6D4,#0891B2)\", color:\"#fff\", fontSize:14, fontWeight:700, fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:8, opacity:!cjEmail||!cjPassword?0.5:1 }}>\n                  {cjMut.isPending ? \"Connecting…\" : \"Connect CJDropshipping\"}\n                </button>\n              </div>\n            </div>\n          </div>\n        </div>\n      )}\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/products/page.tsx":"\"use client\";\nimport Link from \"next/link\";\nimport { useState, useRef, useCallback } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api, uploadAPI } from \"../../../lib/api\";\nimport { useCurrency } from \"../../../lib/currency\";\nimport {\n  Package, Plus, Search, Edit2, Trash2, X, Loader2, Upload,\n  ImageIcon, Star, ChevronDown, Zap, Filter, Check, AlertCircle\n} from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\n\n// ── Image Uploader (inline, fully styled) ─────────────────────────────────────\nfunction ImageUploader({ images, onChange, maxImages=8, t, isDark }: any) {\n  const [uploading, setUploading] = useState<string[]>([]);\n  const [selectedIds, setSelectedIds] = useState<string[]>([]);\n  const [bulkAction, setBulkAction] = useState(\"\");\n  const [drag, setDrag] = useState(false);\n  const [err, setErr] = useState(\"\");\n  const ref = useRef<HTMLInputElement>(null);\n\n  const upload = useCallback(async (files: FileList | File[]) => {\n    const arr = Array.from(files).slice(0, maxImages - images.length);\n    if (!arr.length) return;\n    setErr(\"\");\n    for (const file of arr) {\n      if (file.type && !file.type.startsWith(\"image/\")) { setErr(\"Only image files allowed\"); continue; }\n      if (file.size > 10 * 1024 * 1024) { setErr(\"Max 10MB per image\"); continue; }\n      setUploading(p => [...p, file.name]);\n      try {\n        const res = await uploadAPI.image(file);\n        // uploadAPI uses fetch (not axios) so backend {success,data:{url}} is returned directly\n        const url = (res as any)?.data?.url   // normal: {success:true, data:{url}}\n                 || (res as any)?.data?.data?.url  // legacy double-wrapped\n                 || (res as any)?.url;         // fallback\n        if (!url) throw new Error(\"Upload succeeded but no URL returned — check server logs\");\n        onChange([...images, url]);\n      } catch {\n        setErr(\"Upload failed — please try again or use a different image format\");\n      setTimeout(() => setErr(\"\"), 4000);\n      } finally {\n        setUploading(p => p.filter(n => n !== file.name));\n      }\n    }\n  }, [images, maxImages, onChange]);\n\n  const isUp = uploading.length > 0;\n\n  return (\n    <div>\n      {/* Existing images grid */}\n      {images.length > 0 && (\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(4,1fr)\", gap:10, marginBottom:10 }}>\n          {images.map((url: string, i: number) => (\n            <div key={url} style={{ position:\"relative\", aspectRatio:\"1\", borderRadius:12, overflow:\"hidden\", background:t.faint }}>\n              <img src={url} alt=\"\" style={{ width:\"100%\", height:\"100%\", objectFit:\"cover\" }}/>\n              {i===0 && (\n                <div style={{ position:\"absolute\", top:6, left:6, background:V.v500, color:\"#fff\", fontSize:9, fontWeight:700, padding:\"2px 8px\", borderRadius:99 }}>MAIN</div>\n              )}\n              <div style={{ position:\"absolute\", inset:0, background:\"rgba(0,0,0,0.5)\", opacity:0, transition:\"opacity 0.15s\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:6 }}\n                onMouseEnter={e=>(e.currentTarget.style.opacity=\"1\")} onMouseLeave={e=>(e.currentTarget.style.opacity=\"0\")}>\n                {i!==0 && (\n                  <button onClick={()=>{const a=[...images];a.splice(i,1);a.unshift(url);onChange(a);}}\n                    style={{ width:28,height:28,borderRadius:8,background:\"rgba(255,255,255,0.2)\",border:\"none\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}\n                    title=\"Set as main\">\n                    <Star size={12} color=\"#fff\"/>\n                  </button>\n                )}\n                <button onClick={()=>onChange(images.filter((_:string,j:number)=>j!==i))}\n                  style={{ width:28,height:28,borderRadius:8,background:\"rgba(239,68,68,0.8)\",border:\"none\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                  <X size={12} color=\"#fff\"/>\n                </button>\n              </div>\n            </div>\n          ))}\n          {images.length < maxImages && (\n            <button onClick={()=>ref.current?.click()} type=\"button\"\n              style={{ aspectRatio:\"1\",borderRadius:12,border:`2px dashed ${drag?V.v400:t.border}`,background:t.faint,cursor:\"pointer\",display:\"flex\",flexDirection:\"column\",alignItems:\"center\",justifyContent:\"center\",gap:4,color:t.muted,transition:\"all 0.15s\" }}\n              onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)}\n              onDrop={e=>{e.preventDefault();setDrag(false);upload(e.dataTransfer.files)}}>\n              {isUp?<Loader2 size={16} style={{animation:\"spin 0.8s linear infinite\",color:V.v400}}/>:<><Upload size={14}/><span style={{fontSize:10,fontWeight:700}}>Add</span></>}\n            </button>\n          )}\n        </div>\n      )}\n\n      {/* Drop zone (empty state) */}\n      {images.length === 0 && (\n        <div\n          onClick={()=>ref.current?.click()}\n          onDragOver={e=>{e.preventDefault();setDrag(true)}} onDragLeave={()=>setDrag(false)}\n          onDrop={e=>{e.preventDefault();setDrag(false);upload(e.dataTransfer.files)}}\n          style={{ padding:\"32px 20px\",borderRadius:16,border:`2px dashed ${drag?V.v400:t.border}`,background:drag?`${V.v400}08`:t.faint,cursor:\"pointer\",textAlign:\"center\",transition:\"all 0.2s\" }}>\n          {isUp ? (\n            <div style={{ display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:10 }}>\n              <Loader2 size={28} style={{ color:V.v400,animation:\"spin 0.8s linear infinite\" }}/>\n              <p style={{ fontSize:13,color:t.muted,margin:0 }}>Uploading {uploading.length} image{uploading.length>1?\"s\":\"\"}…</p>\n            </div>\n          ) : (\n            <div style={{ display:\"flex\",flexDirection:\"column\",alignItems:\"center\",gap:10 }}>\n              <div style={{ width:52,height:52,borderRadius:16,background:`${V.v400}15`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                <ImageIcon size={22} color={V.v400}/>\n              </div>\n              <div>\n                <p style={{ fontSize:14,fontWeight:700,color:t.text,margin:\"0 0 4px\" }}>\n                  Drop images here or <span style={{ color:V.v400 }}>browse</span>\n                </p>\n                <p style={{ fontSize:12,color:t.muted,margin:0 }}>\n                  All image formats · Max 10MB · Up to {maxImages} images\n                </p>\n              </div>\n              <div style={{ display:\"flex\",alignItems:\"center\",gap:6,padding:\"8px 16px\",borderRadius:10,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,cursor:\"pointer\" }}>\n                <Upload size={13} color=\"#fff\"/>\n                <span style={{ fontSize:13,fontWeight:700,color:\"#fff\" }}>Choose Photos</span>\n              </div>\n            </div>\n          )}\n        </div>\n      )}\n\n      {err && (\n        <div style={{ display:\"flex\",alignItems:\"center\",gap:8,padding:\"8px 12px\",borderRadius:10,background:\"rgba(239,68,68,0.08)\",border:\"1px solid rgba(239,68,68,0.2)\",marginTop:8 }}>\n          <AlertCircle size={13} color={V.red} style={{ flexShrink:0 }}/>\n          <p style={{ fontSize:12,color:V.red,margin:0 }}>{err}</p>\n          <button onClick={()=>setErr(\"\")} style={{ marginLeft:\"auto\",background:\"none\",border:\"none\",cursor:\"pointer\",color:V.red,display:\"flex\" }}><X size={12}/></button>\n        </div>\n      )}\n\n      <p style={{ fontSize:11,color:t.muted,marginTop:6 }}>\n        {images.length}/{maxImages} images · First image is the main display image\n      </p>\n      <input ref={ref} type=\"file\" accept=\"image/*,image/heic,image/heif\" multiple style={{ display:\"none\" }}\n        onChange={e=>{if(e.target.files)upload(e.target.files);e.target.value=\"\";}}/>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n\n// ── Product Modal ─────────────────────────────────────────────────────────────\nfunction ProductModal({ storeId, product, onClose, t, isDark }: any) {\n  const { fmt } = useCurrency();\n  const qc = useQueryClient();\n  const isEdit = !!product?.id;\n\n  const [form, setForm] = useState({\n    name:          product?.name          || \"\",\n    description:   product?.description   || \"\",\n    price:         product?.price?.toString()         || \"\",\n    comparePrice:  product?.comparePrice?.toString()  || \"\",\n    costPrice:     product?.costPrice?.toString()     || \"\",\n    inventory:     product?.inventory?.toString()     || \"0\",\n    category:      product?.category      || \"\",\n    status:        product?.status        || \"ACTIVE\",\n    images:        product?.images        || [] as string[],\n    sku:           product?.sku           || \"\",\n    weight:        product?.weight?.toString()        || \"\",\n  });\n\n  const mut = useMutation({\n    mutationFn: () => {\n      const payload = {\n        name:        form.name,\n        description: form.description,\n        price:       parseFloat(form.price),\n        comparePrice: form.comparePrice ? parseFloat(form.comparePrice) : null,\n        costPrice:   form.costPrice ? parseFloat(form.costPrice) : null,\n        inventory:   parseInt(form.inventory),\n        category:    form.category,\n        status:      form.status,\n        images:      form.images,\n        sku:         form.sku,\n        weight:      form.weight ? parseFloat(form.weight) : null,\n      };\n      return isEdit\n        ? api.put(`/products/${storeId}/${product.id}`, payload)\n        : api.post(`/products/${storeId}`, payload);\n    },\n    onSuccess: () => {\n      toast.success(isEdit ? \"Product updated!\" : \"Product created!\");\n      qc.invalidateQueries({ queryKey: [\"products\"] });\n      onClose();\n    },\n    onError: (e: any) => toast.error(e.response?.data?.message || \"Failed to save\"),\n  });\n\n  const inp = {\n    width:\"100%\", padding:\"10px 14px\", borderRadius:12,\n    border:`1px solid ${t.border}`, background:isDark?\"rgba(255,255,255,0.05)\":\"#F0EDFF\",\n    color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\", boxSizing:\"border-box\" as const,\n  };\n\n  const label = (txt: string) => (\n    <label style={{ display:\"block\", fontSize:11, fontWeight:700, color:t.muted, marginBottom:6, textTransform:\"uppercase\" as const, letterSpacing:\"0.08em\" }}>\n      {txt}\n    </label>\n  );\n\n  return (\n    <div style={{ position:\"fixed\",inset:0,zIndex:50,display:\"flex\",alignItems:\"flex-start\",justifyContent:\"center\",padding:\"20px 16px\",background:\"rgba(0,0,0,0.6)\",backdropFilter:\"blur(8px)\",overflowY:\"auto\" }}\n      onClick={e=>e.target===e.currentTarget&&onClose()}>\n      <motion.div initial={{opacity:0,scale:0.96,y:20}} animate={{opacity:1,scale:1,y:0}} exit={{opacity:0,scale:0.96}}\n        style={{ width:\"100%\",maxWidth:680,borderRadius:20,overflow:\"hidden\",background:isDark?\"#0F0B1E\":\"#fff\",border:`1px solid ${t.border}`,marginTop:20 }}>\n\n        {/* Header */}\n        <div style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",padding:\"18px 24px\",borderBottom:`1px solid ${t.border}` }}>\n          <div>\n            <h3 style={{ fontSize:16,fontWeight:900,color:t.text,margin:\"0 0 2px\" }}>\n              {isEdit ? \"Edit Product\" : \"Add New Product\"}\n            </h3>\n            <p style={{ fontSize:12,color:t.muted,margin:0 }}>\n              {isEdit ? \"Update product details\" : \"Fill in the details to add a product to your store\"}\n            </p>\n          </div>\n          <button onClick={onClose} style={{ border:\"none\",background:t.faint,cursor:\"pointer\",color:t.muted,width:32,height:32,borderRadius:10,display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n            <X size={16}/>\n          </button>\n        </div>\n\n        <div style={{ padding:\"24px\",maxHeight:\"80vh\",overflowY:\"auto\" }}>\n          {/* Images */}\n          <div style={{ marginBottom:20 }}>\n            <label style={{ display:\"block\",fontSize:11,fontWeight:700,color:t.muted,marginBottom:10,textTransform:\"uppercase\" as const,letterSpacing:\"0.08em\" }}>\n              Product Images *\n            </label>\n            <ImageUploader\n              images={form.images}\n              onChange={(imgs: string[]) => setForm(f=>({...f, images:imgs}))}\n              t={t} isDark={isDark}\n            />\n          </div>\n\n          {/* Name + Category */}\n          <div style={{ display:\"grid\",gridTemplateColumns:\"1fr 1fr\",gap:14,marginBottom:14 }}>\n            <div>\n              {label(\"Product Name *\")}\n              <input style={inp} value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} placeholder=\"e.g. Premium Hair Bundle 18 inch\"/>\n            </div>\n            <div>\n              {label(\"Category\")}\n              <input style={inp} value={form.category} onChange={e=>setForm(f=>({...f,category:e.target.value}))} placeholder=\"e.g. Hair, Electronics, Beauty\"/>\n            </div>\n          </div>\n\n          {/* Description */}\n          <div style={{ marginBottom:14 }}>\n            <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:6 }}>\n              {label(\"Description\")}\n              <button type=\"button\"\n                disabled={!form.name || genDesc}\n                onClick={async () => {\n                  if (!form.name || genDesc) return;\n                  setGenDesc(true);\n                  try {\n                    const r = await api.post(\"/kai/smart-chat\", {\n                      storeId,\n                      message: `Write a compelling product description for: \"${form.name}\". ${form.category ? `Category: ${form.category}.` : \"\"} ${form.price ? `Price: ₦${form.price}.` : \"\"} Keep it 2-3 sentences, focus on benefits and why Nigerian buyers would want it. No bullets, no markdown, just clean flowing text.`,\n                    });\n                    const desc = r.data?.data?.message || r.data?.message || \"\";\n                    if (desc) setForm(f => ({ ...f, description: desc.replace(/\\*\\*/g, \"\").trim() }));\n                  } catch { toast.error(\"KIRO couldn't generate — try again\"); }\n                  finally { setGenDesc(false); }\n                }}\n                style={{ display:\"flex\", alignItems:\"center\", gap:5, padding:\"4px 10px\", borderRadius:8, border:`1px solid ${V.v400}30`, background:`${V.v400}10`, color:V.v400, fontSize:11, fontWeight:700, cursor: form.name ? \"pointer\" : \"not-allowed\", opacity: form.name ? 1 : 0.4, fontFamily:\"inherit\" }}>\n                {genDesc ? <Loader2 size={10} style={{ animation:\"spin 0.8s linear infinite\" }}/> : <Zap size={10}/>}\n                {genDesc ? \"Writing…\" : \"KIRO Write\"}\n              </button>\n            </div>\n            <textarea style={{...inp,resize:\"none\",display:\"block\"}} rows={3}\n              value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))}\n              placeholder=\"Describe your product — what it is, who it's for, why they need it...\"/>\n          </div>\n\n          {/* Pricing */}\n          <div style={{ display:\"grid\",gridTemplateColumns:\"1fr 1fr 1fr\",gap:14,marginBottom:14 }}>\n            <div>\n              {label(\"Selling Price *\")}\n              <input style={inp} type=\"number\" value={form.price} onChange={e=>setForm(f=>({...f,price:e.target.value}))} placeholder=\"25000\"/>\n            </div>\n            <div>\n              {label(\"Compare Price\")}\n              <input style={inp} type=\"number\" value={form.comparePrice} onChange={e=>setForm(f=>({...f,comparePrice:e.target.value}))} placeholder=\"35000\"/>\n              <p style={{ fontSize:10,color:t.muted,margin:\"4px 0 0\" }}>Shows as crossed-out price</p>\n            </div>\n            <div>\n              {label(\"Cost Price\")}\n              <input style={inp} type=\"number\" value={form.costPrice} onChange={e=>setForm(f=>({...f,costPrice:e.target.value}))} placeholder=\"12000\"/>\n              <p style={{ fontSize:10,color:t.muted,margin:\"4px 0 0\" }}>For profit tracking only</p>\n            </div>\n          </div>\n\n          {/* Inventory + SKU + Weight */}\n          <div style={{ display:\"grid\",gridTemplateColumns:\"1fr 1fr 1fr\",gap:14,marginBottom:14 }}>\n            <div>\n              {label(\"Stock Quantity\")}\n              <input style={inp} type=\"number\" value={form.inventory} onChange={e=>setForm(f=>({...f,inventory:e.target.value}))} placeholder=\"100\"/>\n            </div>\n            <div>\n              {label(\"SKU\")}\n              <input style={inp} value={form.sku} onChange={e=>setForm(f=>({...f,sku:e.target.value}))} placeholder=\"PROD-001\"/>\n            </div>\n            <div>\n              {label(\"Weight (kg)\")}\n              <input style={inp} type=\"number\" step=\"0.1\" value={form.weight} onChange={e=>setForm(f=>({...f,weight:e.target.value}))} placeholder=\"0.5\"/>\n            </div>\n          </div>\n\n          {/* Status */}\n          <div style={{ marginBottom:20 }}>\n            {label(\"Status\")}\n            <select style={{...inp,cursor:\"pointer\"}} value={form.status} onChange={e=>setForm(f=>({...f,status:e.target.value}))}>\n              <option value=\"ACTIVE\">Active — Visible on your store</option>\n              <option value=\"DRAFT\">Draft — Hidden from customers</option>\n              <option value=\"ARCHIVED\">Archived — No longer available</option>\n            </select>\n          </div>\n\n          {/* Profit preview */}\n          {form.price && form.costPrice && (\n            <div style={{ padding:\"12px 14px\",borderRadius:12,background:`${V.green}08`,border:`1px solid ${V.green}25`,marginBottom:20,display:\"flex\",gap:16,flexWrap:\"wrap\" }}>\n              {[\n                { label:\"Selling Price\", val: parseFloat(form.price) },\n                { label:\"Cost Price\",    val: parseFloat(form.costPrice) },\n                { label:\"Profit\",        val: parseFloat(form.price)-parseFloat(form.costPrice) },\n                { label:\"Margin\",        val: null },\n              ].map(item => (\n                <div key={item.label}>\n                  <p style={{ fontSize:10,color:t.muted,margin:\"0 0 2px\",textTransform:\"uppercase\" as const,letterSpacing:\"0.08em\" }}>{item.label}</p>\n                  <p style={{ fontSize:14,fontWeight:800,color:item.label===\"Profit\"?V.green:t.text,margin:0 }}>\n                    {item.label===\"Margin\"\n                      ? `${Math.round((parseFloat(form.price)-parseFloat(form.costPrice))/parseFloat(form.price)*100)}%`\n                      : fmt(item.val!, true)}\n                  </p>\n                </div>\n              ))}\n            </div>\n          )}\n        </div>\n\n        {/* Footer */}\n        <div style={{ padding:\"16px 24px\",borderTop:`1px solid ${t.border}`,display:\"flex\",gap:10,alignItems:\"center\" }}>\n          <button onClick={onClose} style={{ padding:\"10px 20px\",borderRadius:12,border:`1px solid ${t.border}`,background:\"transparent\",cursor:\"pointer\",color:t.muted,fontSize:13,fontWeight:600,fontFamily:\"inherit\" }}>\n            Cancel\n          </button>\n          <div style={{ flex:1 }}/>\n          {isEdit && (\n            <p style={{ fontSize:11,color:t.muted }}>Last updated: {product.updatedAt ? new Date(product.updatedAt).toLocaleDateString() : \"—\"}</p>\n          )}\n          <button onClick={()=>mut.mutate()} disabled={!form.name||!form.price||mut.isPending}\n            style={{ display:\"flex\",alignItems:\"center\",gap:8,padding:\"10px 24px\",borderRadius:12,border:\"none\",background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,cursor:!form.name||!form.price?\"not-allowed\":\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700,fontFamily:\"inherit\",opacity:!form.name||!form.price?0.5:1 }}>\n            {mut.isPending?<Loader2 size={14} style={{animation:\"spin 0.8s linear infinite\"}}/>:<Check size={14}/>}\n            {mut.isPending?\"Saving…\":isEdit?\"Save Changes\":\"Add Product\"}\n          </button>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\n// ── Main Products Page ────────────────────────────────────────────────────────\nconst STATUSES = [\"ALL\",\"ACTIVE\",\"DRAFT\",\"ARCHIVED\"];\n\nexport default function ProductsPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark?\"#181230\":\"#fff\",\n    border: isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text:   isDark?\"#F0ECFF\":\"#130D2E\",\n    muted:  isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    faint:  isDark?\"rgba(255,255,255,0.03)\":\"rgba(107,53,232,0.03)\",\n  };\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const { fmt, symbol, code } = useCurrency();\n  const qc = useQueryClient();\n\n  const [search,    setSearch]    = useState(\"\");\n  const [status,    setStatus]    = useState(\"ALL\");\n  const [showModal, setShowModal] = useState(false);\n  const [editing,   setEditing]   = useState<any>(null);\n  const [genDesc,   setGenDesc]   = useState(false);\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"products\", storeId, status],\n    queryFn: () => api.get(`/products/${storeId}`, { params: { status: status===\"ALL\"?undefined:status, limit:100 } }).then(r => r.data.data),\n    enabled: !!storeId,\n  });\n\n  const deleteMut = useMutation({\n    mutationFn: (id: string) => api.delete(`/products/${storeId}/${id}`),\n    onSuccess: () => { toast.success(\"Product deleted\"); qc.invalidateQueries({ queryKey:[\"products\"] }); },\n  });\n\n  const products = (data?.products || data || []).filter((p: any) =>\n    !search || p.name?.toLowerCase().includes(search.toLowerCase())\n  );\n\n  const statusColor = (s: string) =>\n    s===\"ACTIVE\"?\"#10B981\" : s===\"DRAFT\"?\"#F59E0B\" : \"#EF4444\";\n\n  return (\n    <div style={{ maxWidth:1100, margin:\"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}}\n        style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:24,flexWrap:\"wrap\",gap:12 }}>\n        <div>\n          <h1 style={{ fontSize:22,fontWeight:900,letterSpacing:\"-0.04em\",color:t.text,margin:\"0 0 4px\" }}>Products</h1>\n          <p style={{ fontSize:13,color:t.muted,margin:0 }}>\n            {products.length} product{products.length!==1?\"s\":\"\"} · Prices in {code} {symbol}\n          </p>\n        </div>\n        <div style={{ display:\"flex\",gap:10 }}>\n          <button onClick={()=>{setEditing(null);setShowModal(true);}}\n            style={{ display:\"flex\",alignItems:\"center\",gap:6,padding:\"9px 18px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",color:\"#fff\",fontSize:13,fontWeight:700,fontFamily:\"inherit\" }}>\n            <Plus size={15}/> Add Product\n          </button>\n        </div>\n      </motion.div>\n\n      {/* Filters */}\n      <div style={{ display:\"flex\",alignItems:\"center\",gap:10,marginBottom:16,flexWrap:\"wrap\" }}>\n        <div style={{ flex:1,minWidth:200,display:\"flex\",alignItems:\"center\",gap:10,padding:\"9px 14px\",borderRadius:12,background:t.faint,border:`1px solid ${t.border}` }}>\n          <Search size={14} style={{ color:t.muted,flexShrink:0 }}/>\n          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder=\"Search products…\"\n            style={{ flex:1,background:\"transparent\",border:\"none\",outline:\"none\",color:t.text,fontSize:13,fontFamily:\"inherit\" }}/>\n        </div>\n        <div style={{ display:\"flex\",gap:6 }}>\n          {STATUSES.map(s => (\n            <button key={s} onClick={()=>setStatus(s)}\n              style={{ padding:\"7px 14px\",borderRadius:10,border:`1px solid ${status===s?\"rgba(107,53,232,0.4)\":t.border}`,background:status===s?\"rgba(107,53,232,0.08)\":\"transparent\",cursor:\"pointer\",fontSize:12,fontWeight:600,color:status===s?V.v400:t.muted,fontFamily:\"inherit\" }}>\n              {s.charAt(0)+s.slice(1).toLowerCase()}\n            </button>\n          ))}\n        </div>\n      </div>\n\n      {/* Product grid */}\n      {isLoading ? (\n        <div style={{ textAlign:\"center\",padding:\"80px 0\",color:t.muted }}>\n          <Loader2 size={28} style={{ margin:\"0 auto 12px\",animation:\"spin 0.8s linear infinite\",color:V.v400 }}/>\n          <p>Loading products…</p>\n        </div>\n      ) : products.length === 0 ? (\n        <motion.div initial={{opacity:0}} animate={{opacity:1}}\n          style={{ textAlign:\"center\",padding:\"80px 20px\",borderRadius:20,background:t.faint,border:`1px solid ${t.border}` }}>\n          <Package size={48} style={{ color:t.muted,margin:\"0 auto 16px\" }}/>\n          <h3 style={{ fontSize:18,fontWeight:800,color:t.text,margin:\"0 0 8px\" }}>No products yet</h3>\n          <p style={{ fontSize:14,color:t.muted,margin:\"0 0 20px\",maxWidth:360,marginLeft:\"auto\",marginRight:\"auto\",lineHeight:1.6 }}>\n            Add your first product and it'll appear here. You can upload photos, set prices, and track inventory.\n          </p>\n          <button onClick={()=>{setEditing(null);setShowModal(true);}}\n            style={{ display:\"inline-flex\",alignItems:\"center\",gap:8,padding:\"11px 22px\",borderRadius:12,background:`linear-gradient(135deg,${V.v500},#3D1C8A)`,border:\"none\",cursor:\"pointer\",color:\"#fff\",fontSize:14,fontWeight:700,fontFamily:\"inherit\" }}>\n            <Plus size={15}/> Add Your First Product\n          </button>\n        </motion.div>\n      ) : (\n        <div style={{ display:\"grid\",gridTemplateColumns:\"repeat(auto-fill,minmax(220px,1fr))\",gap:14 }}>\n          {products.map((p: any, i: number) => {\n            const img = p.images?.[0];\n            const profit = p.costPrice ? p.price - p.costPrice : null;\n            const margin = profit && p.price ? Math.round(profit/p.price*100) : null;\n            return (\n              <motion.div key={p.id} initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:i*0.04}}\n                style={{ borderRadius:16,overflow:\"hidden\",background:t.card,border:`1px solid ${t.border}`,cursor:\"pointer\",transition:\"box-shadow 0.2s\" }}\n                onMouseEnter={e=>(e.currentTarget as HTMLElement).style.boxShadow=\"0 8px 24px rgba(107,53,232,0.12)\"}\n                onMouseLeave={e=>(e.currentTarget as HTMLElement).style.boxShadow=\"none\"}>\n\n                {/* Image */}\n                <div style={{ aspectRatio:\"1\",background:t.faint,position:\"relative\",overflow:\"hidden\" }}>\n                  {img\n                    ? <img src={img} alt={p.name} style={{ width:\"100%\",height:\"100%\",objectFit:\"cover\",transition:\"transform 0.3s\" }}\n                        onMouseEnter={e=>(e.target as HTMLImageElement).style.transform=\"scale(1.05)\"}\n                        onMouseLeave={e=>(e.target as HTMLImageElement).style.transform=\"scale(1)\"}/>\n                    : <div style={{ width:\"100%\",height:\"100%\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                        <Package size={28} style={{ color:t.muted }}/>\n                      </div>\n                  }\n                  {/* Status badge */}\n                  <div style={{ position:\"absolute\",top:8,left:8,background:statusColor(p.status),color:\"#fff\",fontSize:9,fontWeight:700,padding:\"2px 8px\",borderRadius:99 }}>\n                    {p.status}\n                  </div>\n                  {/* Image count */}\n                  {p.images?.length > 1 && (\n                    <div style={{ position:\"absolute\",bottom:8,right:8,background:\"rgba(0,0,0,0.6)\",color:\"#fff\",fontSize:10,fontWeight:700,padding:\"2px 8px\",borderRadius:99 }}>\n                      +{p.images.length-1}\n                    </div>\n                  )}\n                </div>\n\n                <div style={{ padding:\"12px 14px\" }}>\n                  <p style={{ fontSize:13,color:t.muted,margin:\"0 0 3px\",overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\" }}>{p.category||\"—\"}</p>\n                  <p style={{ fontSize:14,fontWeight:700,color:t.text,margin:\"0 0 8px\",overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\" }}>{p.name}</p>\n\n                  <div style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:10 }}>\n                    <div>\n                      <p style={{ fontSize:16,fontWeight:900,color:t.text,margin:0,letterSpacing:\"-0.03em\" }}>{fmt(p.price,true)}</p>\n                      {p.comparePrice && <p style={{ fontSize:11,color:t.muted,textDecoration:\"line-through\",margin:0 }}>{fmt(p.comparePrice,true)}</p>}\n                    </div>\n                    {margin !== null && (\n                      <span style={{ fontSize:10,fontWeight:700,color:V.green,background:\"rgba(16,185,129,0.1)\",padding:\"2px 8px\",borderRadius:99 }}>\n                        {margin}% margin\n                      </span>\n                    )}\n                  </div>\n\n                  <div style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\" }}>\n                    <span style={{ fontSize:11,color:t.muted }}>\n                      {(p.inventory??p.stockQuantity??0).toLocaleString()} in stock\n                    </span>\n                    <div style={{ display:\"flex\",gap:6 }}>\n                      <button onClick={()=>{setEditing(p);setShowModal(true);}}\n                        style={{ width:28,height:28,borderRadius:8,border:`1px solid ${t.border}`,background:t.faint,cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                        <Edit2 size={12} style={{ color:t.muted }}/>\n                      </button>\n                      <button onClick={()=>{if(confirm(\"Delete this product?\"))deleteMut.mutate(p.id);}}\n                        style={{ width:28,height:28,borderRadius:8,border:\"none\",background:\"rgba(239,68,68,0.08)\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\" }}>\n                        <Trash2 size={12} color={V.red}/>\n                      </button>\n                    </div>\n                  </div>\n                </div>\n              </motion.div>\n            );\n          })}\n        </div>\n      )}\n\n      <AnimatePresence>\n        {showModal && (\n          <ProductModal\n            storeId={storeId}\n            product={editing}\n            onClose={()=>{setShowModal(false);setEditing(null);}}\n            t={t}\n            isDark={isDark}\n          />\n        )}\n      </AnimatePresence>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","backend/src/routes/email.routes.ts":"// src/routes/email.routes.ts\nimport { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { emailService } from \"../services/email.service\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { AuthRequest } from \"../middleware/auth\";\n\nconst router = Router();\n\n// POST /api/email/test — send test email to current user\nrouter.post(\"/test\", authenticate, async (req: AuthRequest, res: Response) => {\n  const user = await prisma.user.findUnique({\n    where: { id: req.user!.userId },\n    select: { email: true, name: true },\n  });\n  if (!user) throw new AppError(\"User not found\", 404);\n\n  await emailService.sendTestEmail(user.email, user.name);\n\n  const devMode = !process.env.SMTP_USER || process.env.SMTP_USER.trim() === \"\";\n\n  res.json({\n    success: true,\n    message: devMode\n      ? \"Dev mode: email logged to console (set SMTP_USER in .env to send real emails)\"\n      : `Test email sent to ${user.email}`,\n    devMode,\n  });\n});\n\n// GET /api/email/status — check email config\nrouter.get(\"/status\", authenticate, async (_req: Request, res: Response) => {\n  const devMode = !process.env.SMTP_USER || process.env.SMTP_USER.trim() === \"\";\n  res.json({\n    success: true,\n    data: {\n      configured: !devMode,\n      devMode,\n      smtpHost: process.env.SMTP_HOST || \"smtp.gmail.com\",\n      smtpPort: process.env.SMTP_PORT || \"587\",\n      from:     process.env.EMAIL_FROM || \"DropOS <noreply@dropos.io>\",\n      hint:     devMode ? \"Set SMTP_USER and SMTP_PASS in backend/.env to enable real emails\" : \"Email is configured and active\",\n    },\n  });\n});\n\n// POST /api/email/low-stock-check — manually trigger low stock check for a store\nrouter.post(\"/low-stock-check/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const { storeId } = req.params;\n\n  const store = await prisma.store.findUnique({\n    where: { id: storeId },\n    include: { owner: { select: { email: true, name: true } } },\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  const lowStockProducts = await prisma.product.findMany({\n    where: { storeId, inventory: { lte: 5 } },\n    select: { name: true, sku: true, inventory: true },\n  });\n\n  if (lowStockProducts.length === 0) {\n    return res.json({ success: true, message: \"No low-stock products found\" });\n  }\n\n  await emailService.sendLowStockAlert(\n    store.owner.email,\n    store.owner.name,\n    lowStockProducts,\n    store.name\n  );\n\n  res.json({\n    success: true,\n    message: `Low stock alert sent for ${lowStockProducts.length} product(s)`,\n    data: lowStockProducts,\n  });\n});\n\n\n// POST /api/emails/:storeId/campaigns/:campaignId/send — send to all customers\nrouter.post(\"/:storeId/campaigns/:campaignId/send\", authenticate, async (req: any, res) => {\n  const { storeId, campaignId } = req.params;\n  const { prisma } = require(\"../config/database\");\n  const RESEND_KEY = process.env.RESEND_API_KEY;\n\n  // Get campaign\n  const campaign = await (prisma.emailCampaign as any).findFirst({\n    where: { id: campaignId, storeId },\n  }).catch(() => null);\n\n  if (!campaign) return res.status(404).json({ success: false, message: \"Campaign not found\" });\n  if (campaign.status === \"sent\") return res.status(400).json({ success: false, message: \"Already sent\" });\n\n  // Get store + customers\n  const [store, customers] = await Promise.all([\n    prisma.store.findUnique({ where:{ id: storeId }, select:{ name: true, slug: true } }),\n    prisma.customer.findMany({ where:{ storeId }, select:{ email: true, name: true }, take: 500 }),\n  ]);\n\n  if (!customers.length) return res.status(400).json({ success: false, message: \"No customers to send to\" });\n  if (!RESEND_KEY) return res.status(400).json({ success: false, message: \"Email not configured. Add RESEND_API_KEY in Render environment settings.\" });\n\n  // Send to all customers via Resend\n  const FROM = `${store?.name || \"DropOS Store\"} <hello@droposhq.com>`;\n  let sent = 0, failed = 0;\n\n  for (const customer of customers) {\n    try {\n      await fetch(\"https://api.resend.com/emails\", {\n        method: \"POST\",\n        headers: { Authorization: `Bearer ${RESEND_KEY}`, \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({\n          from: FROM,\n          to: customer.email,\n          subject: campaign.subject,\n          text: campaign.body,\n          html: `<div style=\"font-family:sans-serif;max-width:600px;margin:0 auto\">${(campaign.body || \"\").replace(/\\n/g, \"<br/>\")}</div>`,\n        }),\n      });\n      sent++;\n    } catch { failed++; }\n  }\n\n  // Mark as sent\n  await (prisma.emailCampaign as any).update({\n    where: { id: campaignId },\n    data: { status: \"sent\", sentAt: new Date(), recipients: sent },\n  }).catch(() => {});\n\n  return res.json({ success: true, data: { sent, failed, total: customers.length } });\n});\n\nexport default router;\n\n// POST /api/email/weekly-digest/:storeId — trigger weekly digest for a store\nrouter.post(\"/weekly-digest/:storeId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const store = await prisma.store.findUnique({\n    where:   { id: req.params.storeId },\n    include: { owner: { select: { email: true, name: true } } },\n  });\n  if (!store) throw new AppError(\"Store not found\", 404);\n\n  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);\n  const orders  = await prisma.order.findMany({\n    where:   { storeId: req.params.storeId, createdAt: { gte: weekAgo }, status: \"COMPLETED\" },\n    include: { items: { include: { product: { select: { name: true } } } } },\n  });\n\n  const revenue      = orders.reduce((s, o) => s + Number(o.total), 0);\n  const newCustomers = await prisma.storeCustomer.count({ where: { storeId: req.params.storeId, createdAt: { gte: weekAgo } } });\n\n  // Top product by quantity sold\n  const productCount: Record<string, { name: string; qty: number }> = {};\n  orders.forEach(o => o.items.forEach((i: any) => {\n    const name = i.product?.name || i.productName || \"Unknown\";\n    if (!productCount[name]) productCount[name] = { name, qty: 0 };\n    productCount[name].qty += i.quantity;\n  }));\n  const topProduct = Object.values(productCount).sort((a, b) => b.qty - a.qty)[0]?.name || \"—\";\n\n  await emailService.sendWeeklyDigest(store.owner.email, store.owner.name, {\n    storeName: store.name, revenue, orders: orders.length,\n    newCustomers, topProduct, currency: store.currency || \"USD\",\n  });\n\n  res.json({ success: true, message: \"Weekly digest sent\", data: { revenue, orders: orders.length, newCustomers, topProduct } });\n});\n\n// POST /api/email/refund/:orderId — trigger refund email\nrouter.post(\"/refund/:orderId\", authenticate, async (req: AuthRequest, res: Response) => {\n  const order = await prisma.order.findUnique({\n    where:   { id: req.params.orderId },\n    include: { store: true },\n  });\n  if (!order) throw new AppError(\"Order not found\", 404);\n  const sym = (order.store as any)?.currency === \"NGN\" ? \"₦\" : \"$\";\n  await emailService.sendRefundProcessed(\n    order.customerEmail, order.customerName, order.orderNumber,\n    `${sym}${Number(order.total).toFixed(2)}`, (order.store as any)?.name || \"Store\"\n  );\n  res.json({ success: true, message: \"Refund email sent\" });\n});\n"};
for(const[rel,c]of Object.entries(files)){const p=rel.split('/').join(path.sep);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');console.log('  ✓',rel.split('/').pop());}
